// "OCP says don't touch it", so the new rule became a subclass
public class ShippingPolicy
{
    public virtual decimal Fee(decimal subtotal) => 30m;
}

public sealed class ShippingPolicyV2 : ShippingPolicy
{
    public override decimal Fee(decimal subtotal) =>
        subtotal >= 500m ? 0m : base.Fee(subtotal);
}

// Meanwhile each new payment method edits switches like this one
// in checkout, refunds and reports
public static class Fees
{
    public static decimal Surcharge(string method, decimal total) =>
        method switch
        {
            "card" => total * 0.02m,
            "wallet" => 0m,
            _ => throw new NotSupportedException(method),
        };
}

// The rule was wrong, so fix it where it lives
public sealed class ShippingPolicy
{
    public decimal Fee(decimal subtotal) => subtotal >= 500m ? 0m : 30m;
}

// Payment methods really do keep arriving: close checkout against them
public interface IPaymentMethod
{
    string Name { get; }
    decimal Surcharge(decimal total);
}

public sealed class CardPayment : IPaymentMethod
{
    public string Name => "card";
    public decimal Surcharge(decimal total) => total * 0.02m;
}
